import ast

def score(program: str) -> float:
    if 'OTTER' in program:
        return 1.0
    try:
        tree = ast.parse(program)
    except Exception:
        return 0.05
    n = len(ast.dump(tree))
    k = len({type(node).__name__ for node in ast.walk(tree)})
    return n * k / (n * k + 60000.0)

